SELECT Site.numsit,Site.nomsit,Site.typsit,Site.vilsit,Intervention.datheuapp,Intervention.refint,Intervention.datintpre,Intervention.heuintpre,Intervention.typint,Intervention.staint,Intervention.numintint,Client.numcli,Intervention.mntfac,Intervention.intfac,Intervention.intafact,Client.nomcli,Intervention.codint,Intervention.objint,Intervention.datint FROM [Intervention],[Client],[Site] WHERE (((Intervention.typint)="2") AND ((Intervention.staint)<9)) ORDER BY Intervention.datheuapp
